# BROKEN: user updates profile, then re-reads it -- but the re-read can hit a lagging replica
def update_profile(user_id, new_data):
    leader_db.execute("UPDATE profiles SET ... WHERE user_id = %s", user_id, new_data)
    return redirect("/profile")   # subsequent GET may be routed to ANY replica

def get_profile(user_id):
    return read_replica_pool.query("SELECT * FROM profiles WHERE user_id = %s", user_id)
    # if this replica hasn't caught up yet, returns the OLD profile

# FIXED: route this user's reads to the leader for a short window after they write
def update_profile(user_id, new_data):
    leader_db.execute("UPDATE profiles SET ... WHERE user_id = %s", user_id, new_data)
    mark_recent_writer(user_id, ttl_seconds=10)   # e.g. a short-lived flag in Redis
    return redirect("/profile")

def get_profile(user_id):
    if is_recent_writer(user_id):
        return leader_db.query("SELECT * FROM profiles WHERE user_id = %s", user_id)
    return read_replica_pool.query("SELECT * FROM profiles WHERE user_id = %s", user_id)
